package edu.canteenx.ui;

import edu.canteenx.model.*;
import edu.canteenx.model.MenuItem;
import edu.canteenx.service.CanteenService;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import javax.swing.table.TableRowSorter;
import javax.swing.event.DocumentListener;
import javax.swing.event.DocumentEvent;
import java.awt.*;
import java.io.File;
import java.math.BigDecimal;
import java.time.format.DateTimeFormatter;
import java.util.*;

/** Native Java desktop experience. The service enforces permissions independently of these screens. */
public final class CanteenXFrame extends JFrame {
    private static final Color INK=new Color(30,43,40), GREEN=new Color(29,105,78), PAPER=new Color(247,247,242);
    private final CanteenService service=new CanteenService();
    private User user;
    public CanteenXFrame(){setTitle("CanteenX · Order smart. Skip the queue.");setDefaultCloseOperation(EXIT_ON_CLOSE);setMinimumSize(new Dimension(1050,700));setSize(1200,790);setLocationRelativeTo(null);showLanding();}
    private JPanel page(){JPanel p=new JPanel(new BorderLayout(18,18));p.setBackground(PAPER);p.setBorder(new EmptyBorder(26,32,26,32));return p;}
    private JLabel label(String text,int size,Color color){JLabel l=new JLabel(text);l.setFont(new Font("SansSerif",Font.BOLD,size));l.setForeground(color);return l;}
    private JButton button(String text){JButton b=new JButton(text);b.setFocusPainted(false);b.setBackground(GREEN);b.setForeground(Color.WHITE);b.setFont(new Font("SansSerif",Font.BOLD,13));b.setBorder(new EmptyBorder(11,18,11,18));return b;}
    private void showLanding(){JPanel root=page();JPanel top=new JPanel(new BorderLayout());top.setOpaque(false);top.add(label("CANTEENX  /  CAMPUS DINING",16,INK),BorderLayout.WEST);JLabel status=new JLabel(service.databaseReady()?"● DATABASE CONNECTED":"● DATABASE OFFLINE");status.setForeground(service.databaseReady()?GREEN:new Color(172,74,54));top.add(status,BorderLayout.EAST);root.add(top,BorderLayout.NORTH);
        JPanel center=new JPanel(new GridBagLayout());center.setOpaque(false);GridBagConstraints g=new GridBagConstraints();g.gridx=0;g.anchor=GridBagConstraints.WEST;g.insets=new Insets(6,0,6,0);
        g.gridy=0;center.add(label("Good food. Less waiting.",42,INK),g);g.gridy++;JLabel sub=new JLabel("One campus. Multiple canteens. One seamless experience.");sub.setFont(new Font("SansSerif",Font.PLAIN,18));sub.setForeground(new Color(100,111,103));center.add(sub,g);g.gridy++;g.insets=new Insets(22,0,6,0);JLabel badges=new JLabel("REC CAFE     ·     REC HUT       /       DIGITAL TOKENS, READY WHEN YOU ARE");badges.setForeground(GREEN);badges.setFont(new Font("SansSerif",Font.BOLD,13));center.add(badges,g);g.gridy++;g.insets=new Insets(20,0,6,0);JButton login=button("Sign in to CanteenX  →");login.addActionListener(e->showLogin());center.add(login,g);g.gridy++;JButton setup=new JButton("Set up local demo accounts");setup.addActionListener(e->run(()->{service.ensureDemoAccounts();info("Demo accounts created. Sign in using the credentials listed in README.md.");}));center.add(setup,g);root.add(center,BorderLayout.CENTER);
        JLabel foot=new JLabel("PAYMENTS ARE DEMONSTRATION ONLY   ·   CAMPUS UPI / SMART CARD / CASH ARE NOT PROCESSED");foot.setForeground(new Color(120,126,119));foot.setFont(new Font("SansSerif",Font.PLAIN,11));root.add(foot,BorderLayout.SOUTH);setContentPane(root);}
    private void showLogin(){JPanel p=page();p.add(label("Welcome back",30,INK),BorderLayout.NORTH);JPanel form=new JPanel(new GridBagLayout());form.setOpaque(false);GridBagConstraints g=new GridBagConstraints();g.gridx=0;g.gridy=0;g.anchor=GridBagConstraints.WEST;g.insets=new Insets(8,8,8,8);JTextField email=new JTextField(28);JPasswordField pass=new JPasswordField(28);form.add(new JLabel("Email"),g);g.gridx=1;form.add(email,g);g.gridx=0;g.gridy++;form.add(new JLabel("Password"),g);g.gridx=1;form.add(pass,g);g.gridy++;JButton sign=button("Sign in");form.add(sign,g);g.gridx=0;g.gridy++;JButton back=new JButton("← Back");form.add(back,g);g.gridx=1;JLabel hint=new JLabel("Demo: student@canteenx.local / student123");form.add(hint,g);sign.addActionListener(e->run(()->{user=service.login(email.getText(),new String(pass.getPassword()));showWorkspace();}));back.addActionListener(e->showLanding());p.add(form,BorderLayout.CENTER);setContentPane(p);}
    private void showWorkspace(){JPanel root=page();JPanel header=new JPanel(new BorderLayout());header.setOpaque(false);JPanel titles=new JPanel(new GridLayout(2,1));titles.setOpaque(false);titles.add(label("CANTEENX   /   "+user.roleName(),13,GREEN));titles.add(label("Hi, "+user.getName(),28,INK));header.add(titles,BorderLayout.WEST);JButton out=new JButton("Sign out");out.addActionListener(e->{service.logout(user);user=null;showLanding();});header.add(out,BorderLayout.EAST);root.add(header,BorderLayout.NORTH);JTabbedPane tabs=new JTabbedPane();tabs.setFont(new Font("SansSerif",Font.BOLD,14));if(user instanceof Student s){tabs.addTab("Order",studentOrder(s));tabs.addTab("My orders",studentHistory(s));}else if(user instanceof Shopkeeper s)tabs.addTab("Token desk",shopDesk(s));else if(user instanceof Admin a){tabs.addTab("Menu studio",adminMenu(a));tabs.addTab("Campus pulse",adminReports(a));}root.add(tabs,BorderLayout.CENTER);setContentPane(root);}
    private JComboBox<Canteen> canteenCombo() throws Exception{JComboBox<Canteen> box=new JComboBox<>();for(Canteen c:service.canteens())box.addItem(c);box.setRenderer(new DefaultListCellRenderer(){public Component getListCellRendererComponent(JList<?> l,Object v,int i,boolean s,boolean f){super.getListCellRendererComponent(l,v,i,s,f);if(v instanceof Canteen c)setText(c.name());return this;}});return box;}
    private JPanel studentOrder(Student student){JPanel panel=new JPanel(new BorderLayout(12,12));panel.setBorder(new EmptyBorder(14,14,14,14));JComboBox<Canteen> canteens=new JComboBox<>();DefaultTableModel model=model("ID","Dish","Category","Price (₹)");JTable table=new JTable(model);table.setRowHeight(30);JSpinner quantity=new JSpinner(new SpinnerNumberModel(1,1,50,1));JComboBox<String> payment=new JComboBox<>(new String[]{"CAMPUS_UPI","SMART_CARD","CASH"});DefaultTableModel cartModel=model("Item ID","Dish","Qty");JTable cartTable=new JTable(cartModel);Map<Long,CartLine> cart=new LinkedHashMap<>();JLabel total=new JLabel("Cart total is calculated from trusted menu prices at checkout.");
        TableRowSorter<DefaultTableModel> sorter=new TableRowSorter<>(model);table.setRowSorter(sorter);JTextField search=new JTextField(14);JComboBox<String> categoryFilter=new JComboBox<>(new String[]{"All categories","Breakfast","Beverages","Snacks","Meals"});Runnable applyFilters=()->{String q=search.getText().trim();String cat=(String)categoryFilter.getSelectedItem();java.util.List<RowFilter<Object,Object>> filters=new ArrayList<>();if(!q.isEmpty())filters.add(RowFilter.regexFilter("(?i)"+java.util.regex.Pattern.quote(q),1,2));if(cat!=null&&!cat.equals("All categories"))filters.add(RowFilter.regexFilter("(?i)^"+java.util.regex.Pattern.quote(cat)+"$",2));sorter.setRowFilter(filters.isEmpty()?null:RowFilter.andFilter(filters));};JPanel toolbar=new JPanel(new FlowLayout(FlowLayout.LEFT));toolbar.add(new JLabel("Choose outlet"));toolbar.add(canteens);toolbar.add(new JLabel("Find a dish"));toolbar.add(search);toolbar.add(new JLabel("Category"));toolbar.add(categoryFilter);JButton refresh=new JButton("Refresh menu");toolbar.add(refresh);panel.add(toolbar,BorderLayout.NORTH);search.getDocument().addDocumentListener(new DocumentListener(){public void insertUpdate(DocumentEvent e){applyFilters.run();}public void removeUpdate(DocumentEvent e){applyFilters.run();}public void changedUpdate(DocumentEvent e){applyFilters.run();}});categoryFilter.addActionListener(e->applyFilters.run());JSplitPane split=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,new JScrollPane(table),new JScrollPane(cartTable));split.setResizeWeight(.62);panel.add(split,BorderLayout.CENTER);JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.add(new JLabel("Qty"));actions.add(quantity);JButton add=button("Add selected");actions.add(add);actions.add(new JLabel("Payment demo"));actions.add(payment);JButton checkout=button("Place order  →");actions.add(checkout);actions.add(total);panel.add(actions,BorderLayout.SOUTH);
        Runnable load=()->{try{model.setRowCount(0);Canteen c=(Canteen)canteens.getSelectedItem();if(c!=null)for(MenuItem m:service.menu(c.id(),false))model.addRow(new Object[]{m.id(),m.name(),m.category(),m.price()});}catch(Exception ex){error(ex);}};
        try{for(Canteen c:service.canteens())canteens.addItem(c);}catch(Exception e){error(e);}canteens.addActionListener(e->{cart.clear();cartModel.setRowCount(0);load.run();});refresh.addActionListener(e->load.run());add.addActionListener(e->{int row=table.getSelectedRow();if(row<0){info("Choose a menu item first.");return;}row=table.convertRowIndexToModel(row);long id=((Number)model.getValueAt(row,0)).longValue();int qty=(Integer)quantity.getValue();CartLine old=cart.get(id);cart.put(id,new CartLine(id,qty+(old==null?0:old.quantity())));cartModel.setRowCount(0);cart.forEach((key,line)->cartModel.addRow(new Object[]{key,nameFor(model,key),line.quantity()}));total.setText("Prices confirmed at checkout");});
        checkout.addActionListener(e->run(()->{Canteen c=(Canteen)canteens.getSelectedItem();if(c==null)throw new IllegalStateException("Choose an outlet.");String token=service.placeOrder(student,c.id(),new ArrayList<>(cart.values()),(String)payment.getSelectedItem());cart.clear();cartModel.setRowCount(0);JOptionPane.showMessageDialog(this,"Order confirmed\n\nTOKEN   "+token+"\nOUTLET   "+c.name()+"\nPayment status: DEMO PAID\n\nShow this token at the counter.","Digital token",JOptionPane.INFORMATION_MESSAGE);load.run();}));if(canteens.getItemCount()>0)load.run();return panel;}
    private String nameFor(DefaultTableModel m,long id){for(int i=0;i<m.getRowCount();i++)if(((Number)m.getValueAt(i,0)).longValue()==id)return String.valueOf(m.getValueAt(i,1));return "Item";}
    private JPanel studentHistory(Student student){JPanel p=new JPanel(new BorderLayout(12,12));DefaultTableModel m=model("Token","Outlet","Total (₹)","Status","Created");JTable t=new JTable(m);t.setRowHeight(29);JButton refresh=button("Refresh history");refresh.addActionListener(e->run(()->{m.setRowCount(0);for(OrderReceipt o:service.history(student))m.addRow(new Object[]{o.token(),o.canteen(),o.total(),o.status(),o.createdAt().format(DateTimeFormatter.ofPattern("dd MMM, HH:mm"))});}));p.add(refresh,BorderLayout.NORTH);p.add(new JScrollPane(t),BorderLayout.CENTER);refresh.doClick();return p;}
    private JPanel shopDesk(Shopkeeper shop){JPanel p=new JPanel(new BorderLayout(16,16));p.setBorder(new EmptyBorder(18,18,18,18));JLabel heading=label("Token handover",26,INK);p.add(heading,BorderLayout.NORTH);JTextField token=new JTextField(20);JTextArea details=new JTextArea();details.setEditable(false);details.setFont(new Font(Font.MONOSPACED,Font.PLAIN,15));details.setBorder(new EmptyBorder(14,14,14,14));JPanel bar=new JPanel(new FlowLayout(FlowLayout.LEFT));bar.add(new JLabel("Scan or enter token"));bar.add(token);JButton lookup=button("Verify token");bar.add(lookup);JButton redeem=button("Confirm handover");bar.add(redeem);JPanel work=new JPanel(new BorderLayout(10,10));work.add(bar,BorderLayout.NORTH);work.add(new JScrollPane(details),BorderLayout.CENTER);p.add(work,BorderLayout.CENTER);final CanteenService.TokenDetails[] found={null};lookup.addActionListener(e->run(()->{found[0]=service.inspectToken(shop,token.getText());details.setText("TOKEN      "+found[0].token()+"\nOUTLET     "+found[0].canteen()+"\nSTUDENT    "+found[0].student()+"\nTOTAL      ₹"+found[0].total()+"\nSTATUS     "+found[0].status()+"\n\n"+String.join("\n",found[0].lines()));if(!"PLACED".equals(found[0].status()))info("This token has already been redeemed.");}));redeem.addActionListener(e->run(()->{service.redeem(shop,token.getText());details.append("\n\n✓ HANDED OVER · REDEMPTION RECORDED");found[0]=null;}));return p;}
    private JPanel adminMenu(Admin admin){JPanel p=new JPanel(new BorderLayout(12,12));JComboBox<Canteen> outlet=new JComboBox<>();try{for(Canteen c:service.canteens())outlet.addItem(c);}catch(Exception e){error(e);}DefaultTableModel m=model("ID","Outlet","Dish","Category","Price","Available");JTable t=new JTable(m);t.setRowHeight(28);JButton refresh=button("Refresh");JButton add=button("Add dish");JButton edit=button("Edit selected");JButton delete=button("Archive selected");JPanel bar=new JPanel(new FlowLayout(FlowLayout.LEFT));bar.add(outlet);bar.add(refresh);bar.add(add);bar.add(edit);bar.add(delete);p.add(bar,BorderLayout.NORTH);p.add(new JScrollPane(t),BorderLayout.CENTER);
        Runnable load=()->run(()->{m.setRowCount(0);for(Canteen c:service.canteens())for(MenuItem x:service.menu(c.id(),true))m.addRow(new Object[]{x.id(),c.name(),x.name(),x.category(),x.price(),x.available()});});refresh.addActionListener(e->load.run());outlet.addActionListener(e->{});add.addActionListener(e->menuDialog(admin,null,()->load.run()));edit.addActionListener(e->{int row=t.getSelectedRow();if(row<0){info("Select a dish to edit.");return;}try{long id=((Number)m.getValueAt(row,0)).longValue();MenuItem chosen=null;for(Canteen c:service.canteens())for(MenuItem x:service.menu(c.id(),true))if(x.id()==id)chosen=x;if(chosen!=null)menuDialog(admin,chosen,()->load.run());}catch(Exception ex){error(ex);}});delete.addActionListener(e->{int row=t.getSelectedRow();if(row<0){info("Select a dish to archive.");return;}run(()->{service.deleteMenuItem(admin,((Number)m.getValueAt(row,0)).longValue());load.run();});});load.run();return p;}
    private void menuDialog(Admin admin,MenuItem item,Runnable refresh){try{JComboBox<Canteen> c=canteenCombo();if(item!=null)for(int i=0;i<c.getItemCount();i++)if(c.getItemAt(i).id()==item.canteenId())c.setSelectedIndex(i);JTextField name=new JTextField(item==null?"":item.name()),category=new JTextField(item==null?"":item.category());JTextField price=new JTextField(item==null?"":item.price().toPlainString());JCheckBox available=new JCheckBox("Available for ordering",item==null||item.available());Object[] fields={"Canteen",c,"Dish name",name,"Category",category,"Price in rupees",price,available};if(JOptionPane.showConfirmDialog(this,fields,item==null?"Add menu item":"Edit menu item",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){service.saveMenuItem(admin,item==null?null:item.id(),((Canteen)c.getSelectedItem()).id(),name.getText(),category.getText(),new BigDecimal(price.getText()),available.isSelected());refresh.run();}}catch(Exception e){error(e);}}
    private JPanel adminReports(Admin admin){JPanel p=new JPanel(new BorderLayout(14,14));JTextArea report=new JTextArea();report.setEditable(false);report.setFont(new Font("SansSerif",Font.PLAIN,16));JButton refresh=button("Refresh campus report");JButton export=button("Export CSV…");JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));b.add(refresh);b.add(export);p.add(b,BorderLayout.NORTH);p.add(new JScrollPane(report),BorderLayout.CENTER);refresh.addActionListener(e->run(()->{CanteenService.SalesSummary s=service.summary(admin);StringBuilder text=new StringBuilder("CAMPUS PULSE\n\nOrders             "+s.orders()+"\nWaiting at counter "+s.pending()+"\nRedeemed           "+s.redeemed()+"\nEligible revenue   ₹"+s.revenue()+"\n\nOUTLET COMPARISON\n");for(CanteenService.CanteenMetric m:service.canteenMetrics(admin))text.append(String.format("%-20s %4d orders   ₹%s%n",m.name(),m.orders(),m.revenue()));text.append("\nTOP 10 DISHES\n");for(CanteenService.TopDish d:service.topDishes(admin))text.append(String.format("%-24s %4d sold   ₹%s%n",d.name(),d.quantity(),d.revenue()));report.setText(text.toString());}));export.addActionListener(e->run(()->{JFileChooser f=new JFileChooser();f.setSelectedFile(new File("canteenx_sales_report.csv"));if(f.showSaveDialog(this)==JFileChooser.APPROVE_OPTION){service.exportReport(admin,f.getSelectedFile());info("CSV report exported.");}}));refresh.doClick();return p;}
    private DefaultTableModel model(String...cols){return new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}};}
    private void run(Throwing action){try{action.run();}catch(Exception e){error(e);}}
    private void error(Exception e){String msg=e.getMessage();if(msg==null||msg.isBlank())msg="Something went wrong.";if(msg.contains("Communications link failure")||msg.contains("No suitable driver")||msg.contains("Access denied"))msg="Can't connect to MySQL. Check the server, credentials, and setup steps in README.md.\n\n"+msg;JOptionPane.showMessageDialog(this,msg,"CanteenX",JOptionPane.ERROR_MESSAGE);}
    private void info(String s){JOptionPane.showMessageDialog(this,s,"CanteenX",JOptionPane.INFORMATION_MESSAGE);}
    @FunctionalInterface private interface Throwing{void run()throws Exception;}
}
